INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s2_q1', 'GATE', 'CS', '', 2024, '2', 1, 'subj_CS_ga', '', '', 'MCQ', 1, 0, 'If `'' denotes increasing order of intensity, then the meaning of the words [walk jog sprint] is analogous to [bothered ________ daunted]. Which one of the given options is appropriate to fill the blank?', ARRAY[ARRAY['phased'], ARRAY['phrased'], ARRAY['fazed'], ARRAY['fused']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s2_q2', 'GATE', 'CS', '', 2024, '2', 2, 'subj_CS_ga', '', '', 'MCQ', 1, 0, 'Two wizards try to create a spell using all the four elements, water, air, fire, and earth. For this, they decide to mix all these elements in all possible orders. They also decide to work independently. After trying all possible combination of elements, they conclude that the spell does not work. How many attempts does each wizard make before coming to this conclusion, independently?', ARRAY[ARRAY['24'], ARRAY['48'], ARRAY['16'], ARRAY['12']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s2_q3', 'GATE', 'CS', '', 2024, '2', 3, 'subj_CS_ga', '', '', 'MCQ', 1, 0, 'In an engineering college of 10,000 students, 1,500 like neither their core branches nor other branches. The number of students who like their core branches is 1/4th of the number of students who like other branches. The number of students who like both their core and other branches is 500. The number of students who like their core branches is', ARRAY[ARRAY['1,800'], ARRAY['3,500'], ARRAY['1,600'], ARRAY['1,500']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s2_q4', 'GATE', 'CS', '', 2024, '2', 4, 'subj_CS_ga', '', '', 'MCQ', 1, 0, 'For positive non-zero real variables and , if ln + = 1 [ln() + ln()] ( 2 ) 2 then, the value of + is', ARRAY[ARRAY['1'], ARRAY['1/2'], ARRAY['2'], ARRAY['4']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s2_q5', 'GATE', 'CS', '', 2024, '2', 5, 'subj_CS_ga', '', '', 'MCQ', 2, 0, 'In the sequence 6, 9, 14, x, 30, 41, a possible value of is', ARRAY[ARRAY['25'], ARRAY['21'], ARRAY['18'], ARRAY['20']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s2_q6', 'GATE', 'CS', '', 2024, '2', 6, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Sequence the following sentences in a coherent passage. P: This fortuitous geological event generated a colossal amount of energy and heat that resulted in the rocks rising to an average height of 4 km across the contact zone. Q: Thus, the geophysicists tend to think of the Himalayas as an active geological event rather than as a static geological feature. R: The natural process of the cooling of this massive edifice absorbed large quantities of atmospheric carbon dioxide, altering the earth''s atmosphere and making it better suited for life. S: Many millennia ago, a breakaway chunk of bedrock from the Antarctic Plate collided with the massive Eurasian Plate.', ARRAY[ARRAY['QPSR'], ARRAY['QSPR'], ARRAY['SPRQ'], ARRAY['SRPQ']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s2_q7', 'GATE', 'CS', '', 2024, '2', 7, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'A person sold two different items at the same price. He made 10% profit in one item, and 10% loss in the other item. In selling these two items, the person made a total of', ARRAY[ARRAY['1% profit'], ARRAY['2% profit'], ARRAY['1% loss'], ARRAY['2% loss']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s2_q8', 'GATE', 'CS', '', 2024, '2', 8, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'The pie charts depict the shares of various power generation technologies in the total electricity generation of a country for the years 2007 and 2023. Year Solar Year 2007 5% 2023 Hydro Coal Solar Coal 30% 35% 20% 20% Gas Hydro Gas 25% 35% 15% Wind Wind 5% 10% The renewable sources of electricity generation consist of Hydro, Solar and Wind. Assuming that the total electricity generated remains the same from 2007 to 2023, what is the percentage increase in the share of the renewable sources of electricity generation over this period?', ARRAY[ARRAY['25%'], ARRAY['50%'], ARRAY['77.5%'], ARRAY['62.5%']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s2_q9', 'GATE', 'CS', '', 2024, '2', 9, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'A cube is to be cut into 8 pieces of equal size and shape. Here, each cut should be straight and it should not stop till it reaches the other end of the cube. The minimum number of such cuts required is', ARRAY[ARRAY['3'], ARRAY['4'], ARRAY['7'], ARRAY['8']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s2_q10', 'GATE', 'CS', '', 2024, '2', 10, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'In the 4 � 4 array shown below, each cell of the first three rows has either a cross (X) or a number. The number in a cell represents the count of the immediate neighboring cells (left, right, top, bottom, diagonals) NOT having a cross (X). Given that the last row has no crosses (X), the sum of the four numbers to be filled in the last row is', ARRAY[ARRAY['11'], ARRAY['10'], ARRAY['12'], ARRAY['9']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s2_q11', 'GATE', 'CS', '', 2024, '2', 11, 'subj_CS_cs', '', '', 'MCQ', 2, 0, '8 bytes in 1 cycle from a device to main memory through cycle stealing at regular intervals. Which one of the following is the data transfer rate (in bits per second) of the DMA controller if 1% of the processor cycles are used for DMA?', ARRAY[ARRAY['2,56,000'], ARRAY['3,200'], ARRAY['25,60,000'], ARRAY['32,000']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s2_q12', 'GATE', 'CS', '', 2024, '2', 12, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Let and be the following propositions: : Fail grade can be given. : Student scores more than 50% marks. Consider the statement: "Fail grade cannot be given when student scores more than 50% marks." Which one of the following is the CORRECT representation of the above statement in propositional logic?', ARRAY[ARRAY['� (B)'], ARRAY['(D) �']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s2_q13', 'GATE', 'CS', '', 2024, '2', 13, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider the following C program. Assume parameters to a function are evaluated from right to left. #include <stdio.h> int g(int p) { printf("%d", p); return p; } int h(int q) { printf("%d", q); return q; } void f(int x, int y) { g(x); h(y); } int main() { f(g(10),h(20)); } Which one of the following options is the CORRECT output of the above C program?', ARRAY[ARRAY['20101020'], ARRAY['10202010'], ARRAY['20102010'], ARRAY['10201020']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s2_q14', 'GATE', 'CS', '', 2024, '2', 14, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'The format of a single-precision floating-point number as per the IEEE 754 standard is: Sign Exponent Mantissa (1bit) (8 bits) (23 bits) Choose the largest floating-point number among the following options. Sign Exponent Mantissa 0 0111 1111 1111 1111 1111 1111 1111 111', NULL, NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s2_q15', 'GATE', 'CS', '', 2024, '2', 15, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Let () be the recurrence relation defined as follows: (0) = 1, (1) = 2, and () = 5( - 1) - 6( - 2) for 2 Which one of the following statements is TRUE?', ARRAY[ARRAY['() = (2)'], ARRAY['() = (2)'], ARRAY['() = (3)'], ARRAY['() = (3)']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s2_q16', 'GATE', 'CS', '', 2024, '2', 16, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Let () be a continuous function from to such that () = 1 - (2 - ) Which one of the following options is the CORRECT value of 02 () ?', ARRAY[ARRAY['0'], ARRAY['1'], ARRAY['2'], ARRAY['-1']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s2_q17', 'GATE', 'CS', '', 2024, '2', 17, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Let be the adjacency matrix of a simple undirected graph . Suppose is its own inverse. Which one of the following statements is always TRUE?', ARRAY[ARRAY['is a cycle'], ARRAY['is a perfect matching'], ARRAY['is a complete graph'], ARRAY['There is no such graph']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s2_q18', 'GATE', 'CS', '', 2024, '2', 18, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'When six unbiased dice are rolled simultaneously, the probability of getting all distinct numbers (i.e., 1, 2, 3, 4, 5, and 6) is 1', ARRAY[ARRAY['324'], ARRAY['324'], ARRAY['324']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s2_q19', 'GATE', 'CS', '', 2024, '2', 19, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Once the DBMS informs the user that a transaction has been successfully completed, its effect should persist even if the system crashes before all its changes are reflected on disk. This property is called', ARRAY[ARRAY['durability'], ARRAY['atomicity'], ARRAY['consistency'], ARRAY['isolation']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s2_q20', 'GATE', 'CS', '', 2024, '2', 20, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'In the context of owner and weak entity sets in the ER (Entity-Relationship) data model, which one of the following statements is TRUE?', ARRAY[ARRAY['The weak entity set MUST have total participation in the identifying relationship'], ARRAY['The owner entity set MUST have total participation in the identifying relationship'], ARRAY['Both weak and owner entity sets MUST have total participation in the identifying'], ARRAY['Neither weak entity set nor owner entity set MUST have total participation in the']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s2_q21', 'GATE', 'CS', '', 2024, '2', 21, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider the following two sets: Set X Set Y P. Lexical Analyzer 1. Abstract Syntax Tree Q. Syntax Analyzer 2. Token R. Intermediate Code Generator 3. Parse Tree S. Code Optimizer 4. Constant Folding Which one of the following options is the CORRECT match from Set X to Set Y ?', ARRAY[ARRAY['P � 4; Q � 1; R � 3; S � 2'], ARRAY['P � 2; Q � 3; R � 1; S � 4'], ARRAY['P � 2; Q � 1; R � 3; S � 4'], ARRAY['P � 4; Q � 3; R � 2; S � 1']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s2_q22', 'GATE', 'CS', '', 2024, '2', 22, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Which one of the following regular expressions is equivalent to the language accepted by the DFA given below? 0 1 0 1', ARRAY[ARRAY['01(0 + 101)'], ARRAY['0(1011)0'], ARRAY['01(0101)0'], ARRAY['0(1 + 0101)0']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s2_q23', 'GATE', 'CS', '', 2024, '2', 23, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Node X has a TCP connection open to node Y. The packets from X to Y go through an intermediate IP router R. Ethernet switch S is the first switch on the network path between X and R. Consider a packet sent from X to Y over this connection. Which of the following statements is/are TRUE about the destination IP and MAC addresses on this packet at the time it leaves X?', ARRAY[ARRAY['The destination IP address is the IP address of R'], ARRAY['The destination IP address is the IP address of Y'], ARRAY['The destination MAC address is the MAC address of S'], ARRAY['The destination MAC address is the MAC address of Y']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s2_q24', 'GATE', 'CS', '', 2024, '2', 24, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Which of the following tasks is/are the responsibility/responsibilities of the memory management unit (MMU) in a system with paging-based memory management?', ARRAY[ARRAY['Allocate a new page table for a newly created process'], ARRAY['Translate a virtual address to a physical address using the page table'], ARRAY['Raise a trap when a virtual address is not found in the page table'], ARRAY['Raise a trap when a process tries to write to a page marked with read-only']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s2_q25', 'GATE', 'CS', '', 2024, '2', 25, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider a process P running on a CPU. Which one or more of the following events will always trigger a context switch by the OS that results in process P moving to a non-running state (e.g., ready, blocked)?', ARRAY[ARRAY['P makes a blocking system call to read a block of data from the disk'], ARRAY['P tries to access a page that is in the swap space, triggering a page fault'], ARRAY['An interrupt is raised by the disk to deliver data requested by some other process'], ARRAY['A timer interrupt is raised by the hardware']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
