INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2024_s2_q31', 'GATE', 'CS', '', 2024, '2', 31, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'An instruction format has the following structure: Instruction Number: Opcode destination reg, source reg-1, source reg-2 Consider the following sequence of instructions to be executed in a pipelined processor: I1: DIV R3, R1, R2 I2: SUB R5, R3, R4 I3: ADD R3, R5, R6 I4: MUL R7, R3, R8 Which of the following statements is/are TRUE?', ARRAY[ARRAY['There is a RAW dependency on R3 between I1 and I2'], ARRAY['There is a WAR dependency on R3 between I1 and I3'], ARRAY['There is a RAW dependency on R3 between I2 and I3'], ARRAY['There is a WAW dependency on R3 between I3 and I4']]::text[], NULL, 2, 'GATE Official 2024 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2024/', 'official', 2024, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
